INSERT INTO `EVENTI` (`Titolo`, `DataPubblicazione`, `DataEvento`, `DescrEvento`, `ImgPath`, `Via`, `Citta`) VALUES
('Baffi tra i Petali: Il Giardino Sicuro', '2026-01-29', '2026-06-10', 'Ti piace il giardinaggio ma temi per il tuo micio? Vieni a scoprire quali fiori sono sicuri e quali no! Un workshop all\'aperto circondati da fiori gialli, con un\'area recintata dove i gatti del rifugio possono rincorrere farfalle.', 'assets/images/events/events_1769723798_facecab1.jpeg', 'Via Guido van Rossum, 90', 'Padova'),
('Cacciatori di Sguardi: Birdwatching Feli', '2026-01-29', '2026-09-12', 'Il passatempo preferito dei gatti? Osservare! Dalla sicurezza di una veranda vetrata affacciata sul lago, i nostri mici potranno ammirare anatre e fauna selvatica. Un\'esperienza visiva stimolante per risvegliare la loro tigre interiore.', 'assets/images/events/events_1769723754_da5fb789.jpeg', 'Lungolago Larry Page, 404', 'San Biagio di Callalta'),
('Cipressi e Scodinzolii: Gita sui Colli D', '2026-01-29', '2026-04-25', 'Una camminata elegante tra i viali alberati che dominano la vallata. Scopri angoli nascosti e panorami da cartolina mentre il tuo cane si gode l\'ombra dei cipressi secolari. Un percorso facile, adatto a tutte le taglie ed età.', 'assets/images/events/events_1769721813_0726afa1.jpg', 'trada Seymour Cray, 1', 'Arquà Petrarca'),
('Cloud Gazing', '2026-01-29', '2026-05-02', 'Goditi il bel tempo disteso sull\'erba! Un pomeriggio di \"Cloud Gazing\"; in compagnia del tuo cane e dei nostri dolci ospiti. Niente corse, solo coccole e relax all\'aria aperta. Il modo più dolce per scoprire se c\'è feeling con un nuovo amico.', 'assets/images/events/events_1769719439_fec9b032.jpeg', 'Viale Radia Perlman, 80', 'Vigonza'),
('Cuore Verde: Trekking nella Forra', '2026-01-30', '2026-05-17', 'Immergiti nel respiro della foresta. Un sentiero che scende nel cuore verde della valle, lontano da auto e rumori. Qui i cani possono ritrovare il loro istinto primordiale tra alberi fitti e aria purissima.', 'assets/images/events/events_1769810163_6135b9c7.jpg', 'Sentiero Charles Darwin, 59', 'Belluno'),
('Festa di Natale', '2026-01-30', '2026-12-20', 'A Natale si può fare di più! Fai un regalo ai nostri animali comprando il Candoro e Canettone! Il ricavo permetterà a Babbo Natale di portare tante cose belle ai gattini e cagnolini.\r\n', 'assets/images/events/events_1769805722_525b20b2.jpg', 'Rotonda Niklaus Wirth, 25', 'Padova'),
('Fioritura a 6 Zampe: Colori di Primavera', '2026-01-29', '2026-05-21', 'Immergiti in un mare di fiori viola! Una visita speciale al parco botanico nel momento di massima fioritura. Tra profumi inebrianti e prati curatissimi, sarà l\'occasione perfetta per scattare foto stupende al tuo cane tra i petali.', 'assets/images/events/events_1769809269_33246ecc.jpg', 'Viale Adele Goldberg, 80', 'Valeggio sul Mincio'),
('Giornata del gatto nero', '2026-01-30', '2026-11-17', 'Per sensibilizzare le persone sulle adozioni dei gatti neri, alcune volontarie tratteranno del tema mentre gli ospiti potranno gustarsi il cibo GRATIS del buffet! Subito dopo, chi vuole può venire a vedere i nostri mici neri disponibili per l\'adozione!', 'assets/images/events/events_1769961573_8175cfa2.jpg', 'Via dei Mille Salici, 1', 'Legnaro'),
('Golden Hour: Tramonto tra i Campi', '2026-01-29', '2026-10-24', 'Quando il sole cala, la campagna si accende di magia. Una serata sotto le lucine, tra spaventapasseri e balle di fieno, per godersi il fresco della sera. Musica leggera, relax e tante code felici sotto un cielo infuocato.', 'assets/images/events/events_1769723276_f5e44112.jpg', 'Campo John McCarthy, 56', 'Grantorto'),
('I Colori del Bosco: Caccia al Tesoro', '2026-01-29', '2026-10-24', 'L\'autunno ci regala frutti meravigliosi. Una passeggiata didattica dove impareremo a riconoscere le piante del sottobosco. I cani si divertiranno con giochi di fiuto tra foglie, bacche e tronchi muschiati.', 'assets/images/events/events_1769723555_0c8ee0c3.jpeg', 'Vicolo George Boole, 01', 'Silea'),
('I Giganti del Bosco: Storia e Natura', '2026-01-30', '2026-04-14', 'Se questi alberi potessero parlare! Passeggiata tra castagni e querce secolari. Il muschio morbido e i tronchi enormi sono il parco giochi naturale perfetto per scattare foto fiabesche al tuo amico peloso.', 'assets/images/events/events_1769810194_dbcae690.jpg', 'Bosco Rita Levi-Montalcini, 100', 'Valdobbiadene'),
('Il Respiro della Cascata', '2026-01-29', '2026-07-17', 'Senti il fresco sulla pelle? Un\'escursione avventurosa che ci porterà ai piedi di una cascata nascosta. Il rumore dell\'acqua e l\'aria nebulizzata saranno un toccasana per i nostri amici a 4 zampe dopo la camminata nel bosco.', 'assets/images/events/events_1769723435_d2624524.jpeg', 'Passo Sophie Wilson, 32', 'Schio'),
('L\'Oasi Zen: Passeggiata Botanica', '2026-01-29', '2026-05-23', 'Tra specchi d\'acqua e ninfee in fiore. Una visita guidata in un giardino acquatico dove la calma regna sovrana. L\'ambiente ideale per cani sensibili che hanno bisogno di tranquillità per aprire il loro cuore a un nuovo amico.', 'assets/images/events/events_1769723398_ed758057.jpeg', 'Via James Gosling, 95', 'Valleggio sul Mincio'),
('Licantropi Buoni', '2026-01-30', '2026-02-16', 'Una suggestiva escursione notturna illuminata solo dalla luna piena. Il bosco di notte ha profumi e suoni nuovi tutti da scoprire. Non temere il buio, il tuo cane sarà la tua guida (e noi portiamo le torce!).', 'assets/images/events/events_1769881636_f8f74f7d.jpg', 'Osservatorio Valentina Tereshkova, 62', 'Asiago'),
('Luci di Festa: Natale in Piazza', '2026-01-30', '2026-12-08', 'La magia del Natale brilla per tutti! Porta il tuo amico peloso sotto il grande albero illuminato. Tra foto ricordo e l\'atmosfera festosa, sarà un\'occasione scintillante per incontrare altri amanti degli animali.', 'assets/images/events/events_1769809711_5dbfb120.jpg', 'Piazza Nikola Tesla, 220', 'Cavarzere'),
('Luci sul Canale: Magia d\'Inverno', '2026-01-29', '2026-12-12', 'Passeggiata notturna nel cuore della città illuminata a festa. Le stelle di luce si riflettono nell\'acqua creando un\'atmosfera da fiaba. Copri bene il tuo amico peloso e vieni a vivere l\'incanto del Natale insieme a noi.', 'assets/images/events/events_1769723325_b92fd6bb.jpg', 'Calle Robert Metcalfe, 72', 'Treviso'),
('Misteri di Pietra: Esploriamo le Grotte', '2026-01-30', '2026-03-09', 'C\'è un piccolo esploratore nel tuo cane? Visitiamo insieme gli anfratti e le piccole grotte carsiche dei colli. Un\'avventura fresca e ombreggiata, ideale per le giornate calde, alla scoperta di mondi nascosti.', 'assets/images/events/events_1769810220_a6c1190e.jpg', 'Via Marie Curie, 88', 'Costozza'),
('Orizzonte di Fuoco: Aperitivo in Spiaggi', '2026-01-30', '2026-08-15', 'Quando il cielo si tinge di rosso, la spiaggia diventa magica. Unisciti a noi per salutare il sole che cala. Relax sulla sabbia fresca, chiacchiere e tanta libertà per i nostri amici a 4 zampe in un\'area riservata.', 'assets/images/events/events_1769810039_19daaac1.jpg', 'Lungomare Carl Sagan, 1980', 'Rosolina'),
('Orizzonti d\'Acqua', '2026-01-29', '2026-04-25', 'Il dolce sciabordio dell\'acqua e la pace della natura. Una passeggiata rilassante lungo gli argini e sui moli di legno, lontani dal caos cittadino. Ideale per cani che amano annusare la brezza e osservare le barche che passano lente.', 'assets/images/events/events_1769719023_d5e40d8e.jpg', 'Riviera Vint Cerf, 192', 'Porto Tolle'),
('Piccoli Botanici', '2026-01-30', '2026-04-04', 'La natura è fatta di piccoli dettagli. Una passeggiata lenta per insegnare al tuo cane a usare il naso con delicatezza. Impareremo a riconoscere le erbe spontanee (e quelle da evitare!) in un prato fiorito.', 'assets/images/events/events_1769810134_9eff99cb.jpg', 'Giardino Gregor Mendel, 3', 'Padova'),
('Picnic nel Bosco (Relax) ', '2026-01-29', '2026-03-29', 'Niente scalate oggi, solo natura e relax. Porta una coperta e un pranzo al sacco: passeremo la giornata nel fresco del bosco. Un ambiente calmo e sicuro, perfetto per far socializzare cani timidi che preferiscono annusare piuttosto che correre.', 'assets/images/events/events_1769720096_ef31a415.jpeg', 'Radura Claude Shannon, 01', 'Asiago'),
('Riflessi d\'Acqua: Passeggiata a Venezia', '2026-01-30', '2026-03-18', 'Scopri la \'Piccola Venezia\' insieme al tuo cane. Una camminata tranquilla lungo i canali, dove l\'acqua scorre lenta tra antiche case colorate. L\'ambiente perfetto per socializzare in un contesto urbano ma rilassante.', 'assets/images/events/events_1769808922_20c4bb01.jpg', 'via Federico Faggin, 4004', 'Venezia'),
('Smeraldo Alpino: Gita al Lago', '2026-01-29', '2026-07-18', 'Un colore così intenso da sembrare dipinto! Passeggiata panoramica lungo le rive di questo lago alpino. Cammineremo sulla diga e sui sentieri circostanti, scattando foto incredibili con il contrasto tra l\'acqua turchese e il pelo dei nostri cani.', 'assets/images/events/events_1769723501_2ae836d0.jpeg', 'Strada John von Neumann, 45', 'Auronzo di Cadore'),
('Sua Maestà il Gatto: Un Giorno a Corte', '2026-01-29', '2026-05-17', 'Ogni gatto si sente un re, ed è ora di portarlo nel suo regno! Una visita speciale nelle corti del castello, dove organizzeremo un incontro di adozione con i \'principi\' e le \'principesse\' felini del nostro rifugio in cerca di un trono comodo.', 'assets/images/events/events_1769723720_3d5db691.jpeg', 'Piazza Margaret Hamilton, 11', 'Este'),
('Tuffi nel Ruscello ', '2026-01-29', '2026-07-17', 'Il caldo si fa sentire? Scappiamo in quota! Una passeggiata facile che costeggia un torrente cristallino dove i nostri amici a 4 zampe potranno rinfrescarsi. Tra schizzi d\'acqua e sassi levigati, il divertimento è assicurato per tutti.', 'assets/images/events/events_1769719404_58f36220.jpeg', 'Via Barbara Liskov, 75', 'Asiago'),
('Un tuffo tutti insieme', '2026-01-29', '2026-06-12', 'Sole, mare e code scodinzolanti! Porta il tuo cane a correre sulla battigia insieme ai nostri ospiti del rifugio. Tra un tuffo e una buca nella sabbia, potrebbe nascere un\'amicizia speciale. Unisciti a noi per una giornata di pura libertà!', 'assets/images/events/events_1769719510_49625c38.jpeg', 'Lungomare Hedy Lamarr, 404', 'Rosolina'),
('Una passeggiata nella natura', '2026-01-29', '2026-04-03', 'Temi che il tuo cane si senta solo? Unisciti a noi per una passeggiata nella natura con gli ospiti del rifugio! Troverà sicuramente un compagno di giochi, magari per la vita o anche solo per un pomeriggio indimenticabile.', 'assets/images/events/events_1769719580_af0b3545.jpeg', 'Viale Alan Turing, 42', 'Abano Terme'),
('Vette e Zampe: Trekking ad Alta Quota', '2026-01-29', '2026-08-12', 'Respira l\'aria frizzante delle Dolomiti! Un\'escursione per i binomi più avventurosi, circondati da panorami mozzafiato. Saliremo insieme verso le cime per regalare al tuo cane la libertà di correre su prati infiniti. Scarponi obbligatori!', 'assets/images/events/events_1769809658_6e6866ce.jpeg', 'Passo Guido van Rossum, 10', 'Cortina'),
('Vette e Zampe: Trekking Panoramico ', '2026-01-29', '2026-03-13', 'Allaccia gli scarponi e prepara il guinzaglio! Un\'escursione di media difficoltà per conquistare la vetta insieme. La fatica della salita svanirà davanti al panorama e alla felicità del tuo cane (e del suo nuovo amico peloso del rifugio!).', 'assets/images/events/events_1769719890_b1ca03bb.jpeg', 'Sentiero Dennis Ritchie, 99', 'Asiago'),
('Zen e Fusa: Meditazione Acquatica', '2026-01-29', '2026-04-25', 'L\'acqua scorre limpida sui sassi e il tuo gatto osserva ipnotizzato. Un pomeriggio di relax sensoriale sulle rive del torrente, perfetto per i mici che amano viaggiare nel trasportino o nello zainetto e godersi i suoni della natura in sicurezza.', 'assets/images/events/events_1769723681_c1615b59.jpeg', 'Riva Claude Shannon, 01', 'Cison di Valmarino'),
('Zucche e Zampette', '2026-01-29', '2026-10-31', 'L\'autunno non è mai stato così colorato! Vieni a scegliere la zucca perfetta nel nostro villaggio agricolo. Tra labirinti di fieno e decorazioni arancioni, i cani potranno divertirsi a esplorare mentre noi ci godiamo i sapori della stagione.', 'assets/images/events/events_1769723221_8338bcd7.jpg', 'villaggio delle zucche di Nonno Andrea, 33', 'Villorba');
