INSERT INTO `ANIMALI` (`IDanimale`, `Nome`, `DataNascita`, `DataRegistrazione`, `Sesso`, `Tipo`, `Colore`, `Pelo`, `Taglia`, `Razza`, `DescrFamiglia`, `DescrComportamentale`, `CondizioniMediche`, `Trasporto`, `ImgPath`, `Email`) VALUES
(6, 'Kiba', '2016-01-16', '2026-01-12', 'M', 'Cane', 'Dorato', 'Lungo', 'Grande', 'Golden Retriver', 'Preferisce le famiglie grandi, i bambini lo adorano, gli piace uscire e giocare e soffre molto la solitudine', 'Appassionato di coccole, fa gli occhi dolci per un pezzo di carne. Non abbaia quasi mai, e sporca pochissimo', 'Dermatite facile', 1, 'assets/images/animals/kiba.jpg', 'dani04.erba@gmail.com'),
(43, 'Olly', '2018-10-09', '2026-01-24', 'M', 'Cane', 'Nera', 'Corto', 'Grande', 'Corso, Labrador', 'Una famiglia di adulti, in grado di dargli le attenzioni che merita. \r\nHa bisogno di spazio per potersi muovere e di tempo per poterlo accudire al meglio. \r\nNon è assolutamente adatto a bambini e anziani.', 'È un cane molto diffidente; da piccolo ha subito diversi abusi quindi difficilmente riesce ad essere amichevole. \r\nSe farete parte del suo branco vi amerà e proteggerà incondizionatamente.\r\nÈ un furbacchione, sa di essere alto e quindi tende a cercare di fregarvi il cibo; inoltre è molto simpatico e gli piace fare i dispetti. \r\nAma giocare e correre. E non vi lascerà mai soli, quando si affeziona ad una persona rimarrà per sempre sotto la sua ala protettiva. Davvero un’anima gentile. \r\nÈ estremamente intelligente e nonostante le sue moltissime paure riesce a comprendere le situazioni che lo circondano (anche quelle più fragili).', '', 1, 'assets/images/animals/olly.jpeg', 'angelafavaro6@gmail.com'),
(44, 'Totò', '2014-09-01', '2026-01-24', 'M', 'Cane', 'Biondo', 'Medio', 'Medio', 'Meticcio', 'Una famiglia che non abbia bambini molto piccoli; dai 10 anni in sù non ci sono problemi.', 'È un cagnolino molto amichevole! Ama la compagnia delle persone, a patto che non siano bambini (quelli proprio non gli vanno a genio…).\r\nNon è particolarmente agile ed è un vero pigrone! Anche se il veterinario vi dirà che deve muoversi, quindi passeggiate obbligatorie (ha la prova costume da fare!).\r\nNon ama la compagnia di altri cagnolini, dopo che da piccolo ha perso il suo fratellino Beppe è diventato molto diffidente nei confronti degli altri cani. In compenso adora le persone ed è estremamente tranquillo.', 'Piccola ciste da tenere monitorata', 0, 'assets/images/animals/toto.jpg', 'angelafavaro6@gmail.com'),
(45, 'Briscola', '2009-09-18', '2026-01-24', 'F', 'Gatto', 'Nero', 'Medio', 'Medio', 'Meticcio', 'Una famiglia tranquilla, cerca una persona che sia in grado di darle tanto affetto.', 'Ama le coccole e il divano. Non c\'è molto altro da dire. \r\nAh, ogni tanto si dimentica che deve mangiare, quindi è meglio ricordarglielo. È una pigrona e farà di tutto per muoversi il meno possibile ma è più agile di quello che mostra...non fatevi fregare. \r\nSe avete paura che scappi tranquilli, non scappa. Odia tutti gli altri animali esistenti al mondo. Ama tutti gli umani esistenti al mondo.', '', 1, 'assets/images/animals/briscola.jpg', 'angelafavaro6@gmail.com'),
(49, 'Haiiro', '2025-08-17', '2026-01-24', 'M', 'Cane', 'Grigio', 'Corto', 'Piccolo', 'Levriero Italiano', 'Preferibilmente una casa grande con spazi esterni estesi.', 'È un po\' pazzo. Saltella e si muove un po\' sbilenco! Allegro e giocoso.', '0', 1, 'assets/images/animals/haiiro.jpeg', 'lindorlinor@gmail.com'),
(50, 'Smoky', '2015-10-07', '2026-01-25', 'M', 'Gatto', 'Grigio Tigrato', 'Corto', 'Piccolo', 'Meticcio', 'Cerca alloggio lontano dalla piena città (sarebbe pericoloso per un gatto che va spesso fuori).', 'È un gatto con un indole selvaggia. Preferisce di gran lunga stare all\'aria aperta agli spazi chiusi. Ama le coccole, ma alle sue condizioni (rigorosamente NON in braccio) e quando vuole lui.\r\nOra che si sta facendo vecchietto sta iniziando a godersi anche gli ambienti coperti oltre alla natura.', 'Occhio strano', 1, 'assets/images/animals/smoky.jpg', 'angelafavaro6@gmail.com'),
(58, 'Shaker', '2014-07-14', '2026-01-26', 'M', 'Cane', 'Bianco E Marrone', 'Corto', 'Medio', 'Juck Russell', 'Una famiglia che non mangia la pizza e che gli possa dare tutte le attenzioni', 'Ha bisogno di molte attenzioni. Piange sempre e non si capisce bene cosa voglia. Ha necessità di essere sempre coccolato (ama i grattini sulla pancia). Si sveglia alle 3 di notte perché ha bisogno di fare plin plin. Conosce la parola PIZZA ed è meglio non mangiarla in sua presenza...impazzisce.\r\nMangia solo quando ha fame (la famiglia precedente ha provato più crocchette ma non è un amante...)', 'Vaccinato', 0, 'assets/images/animals/shaker.jpg', 'lindorlinor@gmail.com'),
(59, 'Key', '2014-03-26', '2026-01-26', 'M', 'Cane', 'Marrone E Nero', 'Lungo', 'Piccolo', 'Yorkshire Terrier', 'Una famiglia che lo tratti come il re della casa.', 'Territoriale. Non ama gli altri animali. Gli piace stare in auto.', 'Sterilizzato, problemi di stomaco e gola', 1, 'assets/images/animals/key.jpg', NULL),
(60, 'Briciola', '2025-05-15', '2026-01-26', 'F', 'Gatto', 'Tigrato', 'Medio', 'Piccolo', 'Non Ne Ho Idea', 'Tempo libero per giocare insieme, ma non troppo perché esige i suoi spazi.', 'è una pazza, corre per tutta casa e si infila in ogni scatola. Quando ha finito le energie cerca un angolino morbido per dormire, finché non le viene fame e cerca di azzannarti la mano.', 'Guarda sta benissimo', 1, 'assets/images/animals/briciola.jpg', 'adminangela@gmail.com'),
(61, 'Lilli', '2012-05-08', '2026-01-26', 'F', 'Cane', 'Marrone', 'Corto', 'Medio', 'Meticcio', 'Qualcuno a cui piaccia camminare molto, con il tempo di portare per lunghe passeggiate il proprio cane. È preferibile che non possieda altri animali.', 'Un cane tranquillo che adora fare passeggiate. Affettuosa con le persone, ma gli altri animali domestici le stanno proprio antipatici. Cerca sempre di rubare il cibo ai gatti.', 'Dermatite ricorrente', 0, 'assets/images/animals/lilli.jpg', 'lauraventurini04@gmail.com'),
(62, 'Nuvola', '2016-01-26', '2025-05-07', 'F', 'Cane', 'Bianco E Nero', 'Medio', 'Piccolo', 'Shih Tzu', 'Preferibilmente che sia paziente e servile', 'È una piccola principessina, dotata di un notevole udito selettivo', 'Manca degli incisivi superiori e inferiori, ha quindi sempre la lingua fuori.', 0, 'assets/images/animals/nuvola.jpg', 'adminangela@gmail.com'),
(63, 'Miles', '2025-01-26', '2025-12-07', 'M', 'Gatto', 'Nero', 'Corto', 'Medio', 'Meticcio', 'Qualcuno a cui non dia fastidio se un gatto lo segue in bagno e poi lo fissa intensamente mentre fa i suoi bisogni.', 'È proprio un ruffiano. Molto coccoloso, SOPRATTUTTO se c’è del cibo a portata di mano ma non di zampa. Quando fa le fusa sembra un trattore. Ha una strana ossessione per il water.', 'Otite', 0, 'assets/images/animals/miles.jpg', 'lauraventurini04@gmail.com'),
(64, 'Bianca', '2017-01-13', '2025-11-20', 'F', 'Cane', 'Dorato', 'Medio', 'Piccolo', 'Meticcio', 'Una famiglia che ami giocare all\'aperto.', 'Molto giocosa, ama correre, quindi ha bisogno di un giardino grande!', '', 1, 'assets/images/animals/bianca.jpg', 'ombretta.gaggi.admin@unipd.it'),
(65, 'Ariel', '2021-01-12', '2026-01-25', 'F', 'Gatto', 'Bianco', 'Corto', 'Medio', 'Khao Manee', 'Non è richiesto alcun particolare riguardo alla famiglia che adotterà Ariel. Si può facilmente ambientare in tutte le situazioni (appartamento, casa singola ecc); e a tutte le persona (bambini, adulti ecc).', 'Una gattina estremamente tranquilla. L\'abbiamo recuperata dopo una segnalazione di abbandono ed è quindi molto diffidente.\r\nApprezza molto le coccole.', '', 1, 'assets/images/animals/ariel.jpg', 'admin'),
(66, 'Romeo', '2020-01-17', '2026-01-26', 'M', 'Gatto', 'Tigrato', 'Medio', 'Piccolo', 'Meticcio', 'Una famiglia tranquilla; purtroppoe essendo poco socievole non è adatto ai bambini piccoli.', 'Romeo è un micio che ama la privacy e stare per le sue.\r\nNon è un coccolone, ma anche lui ha un debole per le coccole (ma fatte quando vuole lui)!', '', 1, 'assets/images/animals/romeo.jpg', NULL),
(67, 'Pandora', '2017-01-18', '2026-01-20', 'F', 'Cane', 'Nero A Chiazze Bianche E Marroni', 'Corto', 'Medio', 'Meticcio', 'Data la suo bontà e tranquillità (oltre alla taglia medio-piccola), si adatta ad ogni tipologia di famiglia; anche con bambini piccoli!', 'Una cagnolina molto tranquilla e coccolona.\r\nMolto buona e paziente; ha una passione per la cucina, e infatti il suo sogno è di fare l\'assaggiatrice ufficiale in famiglia!', '', 1, 'assets/images/animals/pandora.jpg', 'dani04.erba@gmail.com'),
(74, 'Marte', '2019-10-07', '2026-01-27', 'M', 'Cane', 'Bianco E Marrone', 'Corto', 'Grande', 'San Bernardo', 'Una famiglia dinamica; che sia in grado di sostenere il lavoro che un cane di questa taglia richiede.', 'Un cane molto affettuoso! Ama le coccole e ama giocare con altri animali.\r\nÈ buono e paziente con tutti.\r\nGli piace molto andare a passeggiare e rotolarsi sulla neve.', '', 0, 'assets/images/animals/marte.jpeg', NULL),
(75, 'Burz', '2019-10-09', '2026-01-27', 'M', 'Cane', 'Bianco, Marrone, Nero', 'Lungo', 'Grande', 'Bovaro Del Bernese', 'Una famiglia che non abbia più di un cane presente. Essendo Burtz un capobranco non sarebbe facile inserirlo in un branco di cagnolini già formato.', 'Un vero capo branco! Burtz è un cane giocherellone che ama il contatto con le persone.', 'Displasia dell\'anca destra', 1, 'assets/images/animals/burz.jpeg', 'ombretta.gaggi.admin@unipd.it'),
(77, 'Ren', '2017-07-09', '2026-01-27', 'M', 'Cane', 'Bianco, Nero, Marrone', 'Lungo', 'Grande', 'Bovaro Del Bernese', 'Adatto a qualsiasi famiglia!', 'Un cane anziano e molto buono. Paziente con tutti grandi e piccini. Appena vede qualcuno si fionda in cerca di coccole.', '', 0, 'assets/images/animals/ren.jpeg', NULL),
(89, 'Maurice Ravel', '2016-10-15', '2026-01-24', 'M', 'Gatto', 'Nero', 'Corto', 'Medio', 'Meticcio', 'Idealmente una famiglia che non abbia bambini piccoli perché potrebbe fargli involontariamente male. Ma qualsiasi altro tipo di ambiente va bene.', 'Ha sicuramente qualche problema psichiatrico. Può essere comparato ad uno scienziato pazzo; ama conoscere tutta l’oggettistica e il mobilio della casa; se arriva un nuovo oggetto deve essere ispezionato da lui (anche a costo di frantumarlo in mille pezzi). \r\nE’ molto simpatico; può sembrare mono-espressivo ma in realtà è un tenerone capace di dare tantissimo affetto.\r\nAma il contatto con gli umani e cerca sempre di essere presente nelle situazioni di convivialità anche con gli ospiti.\r\nBisogna fare attenzione perché è un giocherellone e a volte morde senza preavviso (essendo lui grande può fare male). \r\nIl suo migliore amico è un cagnolino di nome Totò; va d’accordo con tutti gli animali.', '', 1, 'assets/images/animals/maurice.jpeg', 'angelafavaro6@gmail.com'),
(101, 'Spicy', '2023-06-17', '2026-01-30', 'F', 'Gatto', 'Tigrato Chiaro', 'Corto', 'Piccolo', 'Meticcio', 'Una famiglia che le possa dare tutto l\'affetto e le attenzioni di cui necessita.', 'Ama giocare, stare all\'aperto e le coccole. Le piace tanto mangiare ma bisogna stare attenti a non darle troppo cibo.', 'Sterilizzata', 1, 'assets/images/animals/spicy.jpeg', 'ombretta.gaggi.admin@unipd.it'),
(102, 'Maua', '2024-07-17', '2026-01-30', 'F', 'Gatto', 'Bianco E Nero', 'Corto', 'Medio', 'Meticcio', 'Famiglia attiva ed energetica.', 'Adora stare con le persone e ha sempre bisogno di stimoli e movimento.', '', 1, 'assets/images/animals/maua.jpeg', 'admin'),
(103, 'Felek', '2019-11-17', '2026-01-30', 'M', 'Gatto', 'Tigrato E Bianco', 'Corto', 'Medio', 'Meticcio', 'Una famiglia molto comprensiva, molto.', 'A volte è tranquillo, altre impazzisce e corre ovunque. A volte gli puoi stare simpatico, altre no.', '', 0, 'assets/images/animals/felek.jpeg', 'admin'),
(104, 'Sally', '2017-11-30', '2026-01-30', 'F', 'Cane', 'Nerio, Marrone E Bianco', 'Corto', 'Piccolo', 'Meticcio', 'Una famiglia senza altri animali, perché se osi coccolare qualcosa che non sia lei si mette in un angolino a fare l’offesa.', 'Molto affettuosa, piange se te ne vai per due minuti. Pretende di dormire con te sul letto, vuole tutte le tue attenzioni.', '', 1, 'assets/images/animals/sally.jpg', 'ombretta.gaggi.admin@unipd.it'),
(105, 'Willow', '2023-05-30', '2026-01-30', 'F', 'Gatto', 'Nero', 'Corto', 'Piccolo', 'Meticcio', 'Qualcuno che le dimostri affetto solo quando è lei a cercarlo. Sarebbe ideale qualcuno che voglia adottare anche suo fratello Miles, dato che spesso giocano insieme.', 'Gattina inizialmente diffidente, ma abbastanza affettuosa una volta che prende confidenza. Alterna momenti di tranquillità a corse casuali per tutta la casa.', '', 1, 'assets/images/animals/willow.jpg', 'lauraventurini04@gmail.com'),
(106, 'Piccione', '2025-10-01', '2026-01-31', 'M', 'Gatto', 'Grigio', 'Senza pelo', 'Piccolo', 'Comune', 'Una famiglia con figli universitari che possono portare l\'animale a lezione!', 'Gli piace ascoltare le lezioni universitarie e entrare nelle soffitte. Non fa molto rumore ma potrebbe sporcare in giro.', '', 0, 'assets/images/animals/piccione.png', 'ombretta.gaggi.admin@unipd.it'),
(113, 'Sally', '2017-11-20', '2026-02-02', 'F', 'Cane', 'Nerio, Marrone E Bianco', 'Corto', 'Piccolo', 'Meticcio', 'Una famiglia senza altri animali, perché se osi coccolare qualcosa che non sia lei si mette in un angolino a fare l’offesa.', 'Molto affettuosa, piange se te ne vai per due minuti. Pretende di dormire con te sul letto, vuole tutte le tue attenzioni.', '0', 1, 'assets/images/animals/sally.jpg', 'lauraventurini04@gmail.com'),
(114, 'Morgana', '2020-05-10', '2026-02-02', 'F', 'Gatto', 'Bianco E Nero', 'Corto', 'Medio', 'Meticcio', 'Una famiglia senza altri animali.', 'Molto coccoloso con le persone, molto cattivo con gli altri gatti.', '0', 0, 'assets/images/animals/morgana.jpg', NULL),
(115, 'Mj', '2024-02-29', '2026-02-02', 'F', 'Gatto', 'Nero E Marroncino', 'Corto', 'Piccolo', 'Meticcio', 'Considerando che la leucemia felina è contagiosa tra altri felini, sarebbe meglio che non ci siano altri felini in famiglia, o che questi ultimi siano affetti dalla medesima condizione. Oltre a questo, le basta una famiglia paziente, pronta a perdonarla per i disastri che ovviamente causerà, e pronta a giocare con lei ed aspettare quando sia Mj ad essere pronta a dare affetto, a modo suo.', 'MJ è una gatta particolare, dimostra affetto solo quando lo vuole lei, non è diffidente degli esseri umani o dei cani ma degli altri gatti si. Le piacciono i posti altri, troverà sempre un modo per raggiungerli e dormirci. Gioca tantissimo con le ombre, salta su i muri cercando di prenderle, e grazie alle sue cosce simili a quelle di un coniglio questi salti sono mooolto in alto. Non ha alcun timore nel risponderti in dietro con un miagolio seccato ogni qualvolta le dici che non può fare qualcosa (che puntualmente farà).', 'leucemia felina', 1, 'assets/images/animals/MJ.jpeg', 'dani04.erba@gmail.com'),
(118, 'Minu', '2025-06-02', '2026-02-02', 'F', 'Gatto', 'Arancione E Bianco', 'Corto', 'Piccolo', 'Meticcio', 'Una famiglia che non la lasci mai in casa da sola, ma con almeno un altro animale a farle compagnia. Soffre molto la solitudine anche se inizialmente sembra cercarla', 'Come vedete, è amante dello studio. Un gattino destinato a crescere molto, diffidente delle persone che reputa sconosciute, si trova bene coi cani. Gioca con qualsiasi cosa e vuole essere coccolata solo quando lo richiede lei', '', 1, 'assets/images/animals/minu.jpeg', 'dani04.erba@gmail.com');
