INSERT INTO `RICHIESTE_ADOZIONI` (`Email`, `IDanimale`, `Trasporto`, `Appunti`, `LetteraPresentazione`, `Stato`, `DataRichiesta`, `DataFineValutazione`, `DataInizioValutazione`) VALUES
('angela.canazza@studenti.unipd.it', 44, 0, 'Lettera di presentazione non conforme alle aspettative.', 'aaa', 'In valutazione', '2026-01-05', '2026-01-26', '2026-01-26'),
('angela.canazza@studenti.unipd.it', 62, 0, 'L\'ho annullata perché il profilo dell\'utente non era affidabile', 'ma che bel cagnolino! lo voglio tutto per me', 'Annullata', '2026-01-27', '2026-01-28', NULL),
('angela.canazza@studenti.unipd.it', 106, 0, NULL, 'Siamo amici di vecchia data! la prima volta che l\'ho visto ero ad algebra e matemtica discreta.', 'Nuova', '2026-01-31', NULL, NULL),
('angelafavaro6@gmail.com', 43, 0, NULL, 'Ciao voglio Ollu', 'In valutazione', '2026-01-26', NULL, '2026-01-31'),
('angelafavarp@gmail.com', 61, 1, 'Non mi sembra molto affidabile la richiedente, meglio considerare altri candidati, Lilli si merita il meglio del meglio', 'Voglio salsiccia lilli', 'In valutazione', '2026-01-29', NULL, '2026-02-02'),
('angyangy@gmail.com', 106, 1, NULL, 'Si allora io ho proprio una famiglia adatta al Piccione; potrei per favore adottarlo?', 'Nuova', '2026-01-31', NULL, NULL),
('linor.sade@studenti.unipd.it', 43, 0, NULL, 'pls pls pls pls pls', 'Nuova', '2026-01-26', NULL, NULL),
('linor.sade@studenti.unipd.it', 49, 1, 'Mmmh non so questa Linor non mi convince molto...sembra un pò una criminale da questa letterina di presentazione.\r\nDA RIVALUTARE', 'Ciao! Mi sto traferendo in una nuova casa e ora ho la possibilità di avere due cani! Il mio primo cane lo ho adottato proprio da voi e sono rimasta soddisfatta della cura che avete avuto. Veniamo al punto: ho deciso di adottare un nuovo cagnolino perchè il mio attuale ha bisogno di un po\' di compagnia! Va molto d\'accordo con i levrieri italiani ed è molto curioso di fare nuove amicizie!', 'Accettata', '2026-01-26', '2026-02-01', '2026-02-01'),
('linor.sade@studenti.unipd.it', 58, 1, 'mi sembra appropriata questa adozione. La lettera di presentazione precedente non la ho cercata e non gliela ho chiesta ma direi che va bene così!', 'Ho precedentemente inviato una richiesta per un altro cane ma mi sono accorta che questo è esattamente uguale a quello che ho già! Anche il nome! Significa che posso chiamarne uno e arrivano entrambi!!!!! Sono emozionata lo voglio subito datemelo pls', 'In valutazione', '2026-01-26', NULL, '2026-02-02'),
('linor.sade@studenti.unipd.it', 65, 0, NULL, 'Voglio collezionare tutti i gatti con un\'espressione buffa. Questo gatto ha un\'espressione buffa. Voglio collezionare questo gatto.', 'Nuova', '2026-02-02', NULL, NULL),
('linor.sade@studenti.unipd.it', 101, 0, NULL, 'I miei amici dicono che non mi piacciono i gatti ma voglio dimostrare che non è così! Si certamente non li amo...ma non li odio nemmeno! Solamente che preferisco i cani...', 'Nuova', '2026-02-02', NULL, NULL),
('linor.sade@studenti.unipd.it', 113, 1, NULL, 'I miei genitori mi hanno detto che non posso avere un cane e ora ne voglio adottare uno senza che lo scoprano. Perfavore mi dai questo cane?', 'Nuova', '2026-02-02', NULL, NULL),
('ombretta.gaggi.user@unipd.it', 44, 0, 'Non so non so...ci penso su', 'Non ho altri animali in casa, quindi avrebbe tutte le mie attenzioni esclusive e non dovrebbe preoccuparsi di interagire con altri cani.', 'In valutazione', '2026-01-31', NULL, '2026-01-31'),
('ombretta.gaggi.user@unipd.it', 63, 0, NULL, 'Ciao! Mi piace molto questo gatto perché mi sembra uno che sa il fatto suo. Posso garantirgli cibo buono e cure, ma senza soffocarlo di attenzioni non richieste.', 'Nuova', '2026-01-31', NULL, NULL),
('ombretta.gaggi.user@unipd.it', 77, 0, 'Per ora non vedo nulla di male, nei prossimi giorni inizieremo a conoscere il candidato', 'Non cerco un cane da portare a fare maratone, ma un compagno fedele con cui condividere la quotidianità. Mi piace molto il fatto che sia socievole e paziente con tutti, perché ho spesso amici o parenti che girano per casa e vorrei un cane che si senta a suo agio in mezzo alla gente senza stress.', 'In valutazione', '2026-01-31', NULL, '2026-01-31'),
('porcoventi@gmail.com', 6, 0, 'non lo so, non mi ispira il fatto che non abbia amici.\r\nAl telefono sembrava dolce', 'Voglio tantissimo questo cane perché sennò sono sempre da solo ho bisogno di un amico', 'Respinta', '2026-01-21', '2026-01-26', '2026-01-26'),
('porcoventi@gmail.com', 44, 0, NULL, 'L\'altro non esiste quindi provo con questo', 'Annullata', '2026-01-24', '2026-01-24', '2026-01-24'),
('porcoventi@gmail.com', 104, 1, 'C\'ha anche ragione', 'Oh è il cane di mia zia datemelo', 'Da trasportare', '2026-01-31', '2026-01-31', '2026-01-31'),
('user', 65, 0, NULL, 'Vorrei tanto questo gattino!', 'Nuova', '2026-02-01', NULL, NULL),
('user', 101, 0, NULL, 'Quanto è bella!', 'Nuova', '2026-02-01', NULL, NULL),
('user', 102, 0, NULL, 'lo vorrei tanto!', 'In valutazione', '2026-02-01', NULL, '2026-02-01'),
('user@gmail.com', 44, 0, NULL, 'm,dmf,.smf.,d', 'Annullata', '2026-01-31', '2026-01-31', NULL);
